"""Quarter statistics must be generated by the actual event engine."""
import numpy as np
from data_sources import demo_dataset
from model import Config, run


def test_quarters_reconcile_to_regulation_and_overtime():
    teams, players = demo_dataset()
    r = run(teams, players, 'BOS', 'NYK', Config(
        iterations=650, seed=61, possession_mode=True,
        calibrate_possession=False))
    q = r['quarter_summary']
    assert q['source'] == 'same possession-event draws as final box scores'
    for team, scores in (('BOS', r['home_score']), ('NYK', r['away_score'])):
        data = q['teams'][team]
        pts = data['quarter_points']
        assert pts.shape == (650, 4)
        assert np.all(pts >= 0)
        assert np.all(pts.sum(axis=1) <= scores)
        assert np.isclose(sum(data['quarter_mean_points']) +
                          data['overtime_mean_points_all_games'], scores.mean(), atol=.008)
        assert np.allclose(np.cumsum(pts, axis=1).mean(axis=0),
                           data['end_of_quarter_mean_score'], atol=.001)
        assert np.allclose(data['quarter_player_means']['PTS'].sum(axis=1),
                           data['quarter_mean_points'], atol=.01)
        assert np.allclose(data['quarter_player_means']['MIN'].sum(axis=1),
                           [60, 60, 60, 60], atol=1.0)
        assert np.allclose(data['quarter_event_means']['FGA'],
                           data['quarter_player_means']['FGA'].sum(axis=1), atol=.02)


def test_baseline_does_not_fabricate_quarter_events():
    teams, players = demo_dataset()
    r = run(teams, players, 'BOS', 'NYK', Config(iterations=100, seed=1))
    assert r['quarter_summary'] is None
